// One handshake = 1 RTT of setup before the first byte of data.
const rttMs = { lan: 0.5, sameRegion: 12, intercontinental: 150 };

function handshakeSetupCost(rtt) {
  // SYN -> SYN-ACK -> ACK completes in one full round-trip
  return rtt * 1;
}

for (const [link, rtt] of Object.entries(rttMs)) {
  console.log(`${link}: handshake adds ${handshakeSetupCost(rtt)} ms before data`);
}
